-- db23countsSql
SELECT UTC_TIMESTAMP() sampled_utc,(SELECT COUNT(*) FROM `GW001_IMC Results`) results_n,(SELECT COUNT(*) FROM `GW001_IMC Match Report`) reports_n,(SELECT COUNT(*) FROM `IMC Site Results` WHERE game_world_id='GW001') site_results_n,(SELECT COUNT(*) FROM `IMC Site Match Report` WHERE game_world_id='GW001') site_reports_n,(SELECT total_records FROM `IMC Repository Report` WHERE game_world_id='GW001' AND repository='IMC Results') results_report_n,(SELECT total_records FROM `IMC Repository Report` WHERE game_world_id='GW001' AND repository='IMC Match Report') match_report_n,(SELECT MAX(imported_at) FROM `GW001_IMC Match Report`) latest_import,(SELECT COUNT(*) FROM `GW001_IMC Results` r LEFT JOIN `GW001_IMC Match Report` m ON r.sm_fixture_id=m.sm_fixture_id AND r.game_world_id=m.game_world_id WHERE m.sm_fixture_id IS NULL) not_loaded,(SELECT COUNT(*) FROM `GW001_IMC Match Report` m LEFT JOIN `GW001_IMC Results` r ON r.sm_fixture_id=m.sm_fixture_id AND r.game_world_id=m.game_world_id WHERE r.sm_fixture_id IS NULL) orphans;

-- db23validationSql
SELECT 'GW001_IMC Results' dataset,COUNT(*) playoff_n,SUM(d IS NULL) unresolved_division,SUM(NOT(CAST(sm_division AS BINARY)<=>CAST(d AS BINARY))) wrong_division,SUM(NOT(CAST(competition_key AS BINARY)<=>CAST(CONCAT_WS('|','GW001','DOMESTIC','playoff',d) AS BINARY))) wrong_key FROM (SELECT x.*,(SELECT CASE WHEN h.division_value IN ('2','3','4') AND h.division_value=a.division_value AND h.club_division=h.division_value AND a.club_division=a.division_value THEN h.division_value ELSE NULL END FROM gw_world_clubs h JOIN gw_world_clubs a ON a.game_world_id=h.game_world_id JOIN gw_source_captures hc ON hc.capture_id=h.capture_id AND hc.game_world_id=h.game_world_id AND hc.capture_status='complete' JOIN gw_source_captures ac ON ac.capture_id=a.capture_id AND ac.game_world_id=a.game_world_id AND ac.capture_status='complete' WHERE h.game_world_id='GW001' AND h.world_club_id=x.home_sm_club_id AND a.world_club_id=x.away_sm_club_id AND hc.generated_at < DATE_ADD(x.match_date,INTERVAL 1 DAY) AND ac.generated_at < DATE_ADD(x.match_date,INTERVAL 1 DAY)) d FROM `GW001_IMC Results` x WHERE x.game_world_id='GW001' AND (REGEXP_LIKE(TRIM(COALESCE(x.sm_action,'')), '^play[[:space:]-]*offs?$', 'i') OR REGEXP_LIKE(TRIM(COALESCE(x.competition_stage,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(x.competition_group_name,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(x.competition_round,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i'))) q UNION ALL SELECT 'GW001_IMC Match Report' dataset,COUNT(*) playoff_n,SUM(d IS NULL) unresolved_division,SUM(NOT(CAST(sm_division AS BINARY)<=>CAST(d AS BINARY))) wrong_division,SUM(NOT(CAST(competition_key AS BINARY)<=>CAST(CONCAT_WS('|','GW001','DOMESTIC','playoff',d) AS BINARY))) wrong_key FROM (SELECT x.*,(SELECT CASE WHEN h.division_value IN ('2','3','4') AND h.division_value=a.division_value AND h.club_division=h.division_value AND a.club_division=a.division_value THEN h.division_value ELSE NULL END FROM gw_world_clubs h JOIN gw_world_clubs a ON a.game_world_id=h.game_world_id JOIN gw_source_captures hc ON hc.capture_id=h.capture_id AND hc.game_world_id=h.game_world_id AND hc.capture_status='complete' JOIN gw_source_captures ac ON ac.capture_id=a.capture_id AND ac.game_world_id=a.game_world_id AND ac.capture_status='complete' WHERE h.game_world_id='GW001' AND h.world_club_id=x.home_sm_club_id AND a.world_club_id=x.away_sm_club_id AND hc.generated_at < DATE_ADD(x.match_date,INTERVAL 1 DAY) AND ac.generated_at < DATE_ADD(x.match_date,INTERVAL 1 DAY)) d FROM `GW001_IMC Match Report` x WHERE x.game_world_id='GW001' AND ((REGEXP_LIKE(TRIM(COALESCE(x.sm_action,'')), '^play[[:space:]-]*offs?$', 'i') OR REGEXP_LIKE(TRIM(COALESCE(x.competition_stage,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(x.competition_round,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i')) OR EXISTS (SELECT 1 FROM `GW001_IMC Results` r WHERE r.game_world_id=x.game_world_id AND r.sm_fixture_id=x.sm_fixture_id AND r.home_sm_club_id=x.home_sm_club_id AND r.away_sm_club_id=x.away_sm_club_id AND r.match_date=x.match_date AND (REGEXP_LIKE(TRIM(COALESCE(r.sm_action,'')), '^play[[:space:]-]*offs?$', 'i') OR REGEXP_LIKE(TRIM(COALESCE(r.competition_stage,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(r.competition_group_name,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i') OR REGEXP_LIKE(TRIM(COALESCE(r.competition_round,'')), '^play[[:space:]-]*offs?([[:space:]:-]|$)', 'i'))))) q;

