T(r.`aggregate_away_score` AS BINARY)<=>CAST(s.`aggregate_away_score` AS BINARY) AND CAST(r.`result_status` AS BINARY)<=>CAST(s.`result_status` AS BINARY) AND CAST(r.`fingerprint` AS BINARY)<=>CAST(s.`fingerprint` AS BINARY) AND CAST(r.`imported_at` AS BINARY)<=>CAST(s.`imported_at` AS BINARY))) divergent FROM `GW001_IMC Results` r LEFT JOIN `IMC Site Results` s ON r.sm_fixture_id=s.sm_fixture_id AND s.game_world_id='GW001' UNION ALL SELECT 'GW001_IMC Match Report' dataset,COUNT(*) raw_n,COUNT(DISTINCT r.sm_fixture_id) fixtures_n,SUM(r.game_world_id <> 'GW001' OR r.game_world_id IS NULL) bad_gw,(SELECT COUNT(*) FROM `IMC Site Match Report` WHERE game_world_id='GW001') site_n,SUM(s.sm_fixture_id IS NULL) missing,SUM(s.sm_fixture_id IS NOT NULL AND NOT(CAST(r.`game_world_id` AS BINARY)<=>CAST(s.`game_world_id` AS BINARY) AND CAST(r.`sm_fixture_id` AS BINARY)<=>CAST(s.`sm_fixture_id` AS BINARY) AND CAST(r.`competition_key` AS BINARY)<=>CAST(s.`competition_key` AS BINARY) AND CAST(r.`sm_action` AS BINARY)<=>CAST(s.`sm_action` AS BINARY) AND CAST(r.`sm_country` AS BINARY)<=>CAST(s.`sm_country` AS BINARY) AND CAST(r.`sm_division` AS BINARY)<=>CAST(s.`sm_division` AS BINARY) AND CAST(r.`competition_group` AS BINARY)<=>CAST(s.`competition_group` AS BINARY) AND CAST(r.`competition_stage` AS BINARY)<=>CAST(s.`competition_stage` AS BINARY) AND CAST(r.`competition_round` AS BINARY)<=>CAST(s.`competition_round` AS BINARY) AND CAST(r.`match_date` AS BINARY)<=>CAST(s.`match_date` AS BINARY) AND CAST(r.`home_sm_club_id` AS BINARY)<=>CAST(s.`home_sm_club_id` AS BINARY) AND CAST(r.`home_name` AS BINARY)<=>CAST(s.`home_name` AS BINARY) AND CAST(r.`away_sm_club_id` AS BINARY)<=>CAST(s.`away_sm_club_id` AS BINARY) AND CAST(r.`away_name` AS BINARY)<=>CAST(s.`away_name` AS BINARY) AND CAST(r.`home_sm_manager_id` AS BINARY)<=>CAST(s.`home_sm_manager_id` AS BINARY) AND CAST(r.`home_manager_name` AS BINARY)<=>CAST(s.`home_manager_name` AS BINARY) AND CAST(r.`away_sm_manager_id` AS BINARY)<=>CAST(s.`away_sm_manager_id` AS BINARY) AND CAST(r.`away_manager_name` AS BINARY)<=>CAST(s.`away_manager_name` AS BINARY) AND CAST(r.`home_score` AS BINARY)<=>CAST(s.`home_score` AS BINARY) AND CAST(r.`away_score` AS BINARY)<=>CAST(s.`away_score` AS BINARY) AND CAST(r.`penalty_home_score` AS BINARY)<=>CAST(s.`penalty_home_score` AS BINARY) AND CAST(r.`penalty_away_score` AS BINARY)<=>CAST(s.`penalty_away_score` AS BINARY) AND CAST(r.`aggregate_home_score` AS BINARY)<=>CAST(s.`aggregate_home_score` AS BINARY) AND CAST(r.`aggregate_away_score` AS BINARY)<=>CAST(s.`aggregate_away_score` AS BINARY) AND CAST(r.`stadium_name` AS BINARY)<=>CAST(s.`stadium_name` AS BINARY) AND CAST(r.`attendance` AS BINARY)<=>CAST(s.`attendance` AS BINARY) AND CAST(r.`team_stats_json` AS BINARY)<=>CAST(s.`team_stats_json` AS BINARY) AND CAST(r.`players_json` AS BINARY)<=>CAST(s.`players_json` AS BINARY) AND CAST(r.`events_json` AS BINARY)<=>CAST(s.`events_json` AS BINARY) AND CAST(r.`tactics_json` AS BINARY)<=>CAST(s.`tactics_json` AS BINARY) AND CAST(r.`commentary_json` AS BINARY)<=>CAST(s.`commentary_json` AS BINARY) AND CAST(r.`fingerprint` AS BINARY)<=>CAST(s.`fingerprint` AS BINARY) AND CAST(r.`imported_at` AS BINARY)<=>CAST(s.`imported_at` AS BINARY))) divergent FROM `GW001_IMC Match Report` r LEFT JOIN `IMC Site Match Report` s ON r.sm_fixture_id=s.sm_fixture_id AND s.game_world_id='GW001';

-- db23reportSql
SELECT 'missing_or_different' test,COUNT(*) n FROM (SELECT 'TOTAL' scope,'' sm_action,'' sm_country,'' competition_key,COUNT(*) n FROM `GW001_IMC Results` UNION ALL SELECT 'SM_ACTION',COALESCE(sm_action,''),'','',COUNT(*) FROM `GW001_IMC Results` GROUP BY sm_action UNION ALL SELECT 'COMPETITION_KEY','','',COALESCE(competition_key,''),COUNT(*) FROM `GW001_IMC Results` GROUP BY competition_key UNION ALL SELECT 'SM_ACTION_COMPETITION_KEY',COALESCE(sm_action,''),'',COALESCE(competition_key,''),COUNT(*) FROM `GW001_IMC Results` GROUP BY sm_action,competition_key) e LEFT JOIN `IMC Results Report` p ON p.game_world_id='GW001' AND p.scope=e.scope AND p.sm_action=e.sm_action AND p.sm_country=e.sm_country AND p.competition_key=e.competition_key WHERE p.scope IS NULL OR p.total_results<>e.n UNION ALL SELECT 'unexpected_nonzero',COUNT(*) FROM `IMC Results Report` p LEFT JOIN (SELECT 'TOTAL' scope,'' sm_action,'' sm_country,'' competition_key,COUNT(*) n FROM `GW001_IMC Results` UNION ALL SELECT 'SM_ACTION',COALESCE(sm_action,''),'','',COUNT(*) FROM `GW001_IMC Results` GROUP BY sm_action UNION ALL SELECT 'COMPETITION_KEY','','',COALESCE(competition_key,''),COUNT(*) FROM `GW001_IMC Results` GROUP BY competition_key UNION ALL SELECT 'SM_ACTION_COMPETITION_KEY',COALESCE(sm_action,''),'',COALESCE(competition_key,''),COUNT(*) FROM `GW001_IMC Results` GROUP BY sm_action,competition_key) e ON p.scope=e.scope AND p.sm_action=e.sm_action AND p.sm_country=e.sm_country AND p.competition_key=e.competition_key WHERE p.game_world_id='GW001' AND e.scope IS NULL AND p.total_results<>0;

-- db23congruenceSql
SELECT UTC_TIMESTAMP() sampled_utc,COUNT(*) linked,SUM(NOT(r.`game_world_id`<=>m.`game_world_id`)) `game_world_id`,SUM(NOT(r.`sm_fixture_id`<=>m.`sm_fixture_id`)) `sm_fixture_id`,SUM(NOT(r.`competition_key`<=>m.`competition_key`)) `competition_key`,SUM(NOT(r.`sm_action`<=>m.`sm_action`)) `sm_action`,SUM(NOT(r.`sm_country`<=>m.`sm_country`)) `sm_country`,SUM(NOT(r.`sm_division`<=>m.`sm_division`)) `sm_division`,SUM(NOT(r.`competition_group`<=>m.`competition_group`)) `competition_group`,SUM(NOT(r.`competition_stage`<=>m.`competition_stage`)) `competition_stage`,SUM(NOT(r.`competition_round`<=>m.`competition_round`)) `competition_round`,SUM(NOT(r.`match_date`<=>m.`match_date`)) `match_date`,SUM(NOT(r.`home_sm_club_id`<=>m.`home_sm_club_id`)) `home_sm_club_id`,SUM(NOT(r.`home_name`<=>m.`home_name`)) `home_name`,SUM(NOT(r.`away_sm_club_id`<=>m.`away_sm_club_id`)) `away_sm_club_id`,SUM(NOT(r.`away_name`<=>m.`away_name`)) `away_name`,SUM(NOT(r.`home_score`<=>m.`home_score`)) `home_score`,SUM(NOT(r.`away_score`<=>m.`away_score`)) `away_score`,SUM(NOT(r.`penalty_home_score`<=>m.`penalty_home_score`)) `penalty_home_score`,SUM(NOT(r.`penalty_away_score`<=>m.`penalty_away_score`)) `penalty_away_score`,SUM(NOT(r.`aggregate_home_score`<=>m.`aggregate_home_score`)) `aggregate_home_score`,SUM(NOT(r.`aggregate_away_score`<=>m.`aggregate_away_score`)) `aggregate_away_score`,SUM((r.home_sm_manager_id IS NULL)<>(m.home_sm_manager_id IS NULL)) home_manager_missing_one_side,SUM((r.away_sm_manager_id IS NULL)<>(m.away_sm_manager_id IS NULL)) away_manager_missing_one_side,SUM(r.home_sm_manager_id IS NOT NULL AND m.home_sm_manager_id IS NOT NULL AND r.home_sm_manager_id<>m.home_sm_manager_id) home_manager_conflict,SUM(r.away_sm_manager_id IS NOT NULL AND m.away_sm_manager_id IS NOT NULL AND r.away_sm_manager_id<>m.away_sm_manager_id) away_manager_conflict,SUM(NOT(CAST(r.home_name AS BINARY)<=>CAST(m.home_name AS BINARY))) home_name_byte_diff,SUM(NOT(CAST(r.away_name AS BINARY)<=>CAST(m.away_name AS BINARY))) away_name_byte_diff FROM `GW001_IMC Results` r JOIN `GW001_IMC Match Report` m ON r.game_world_id=m.game_world_id AND r.sm_fixture_id=m.sm_fixture_id;